diff --git a/tests/repro/no-useless-assignment-try-catch.js b/tests/repro/no-useless-assignment-try-catch.js
new file mode 100644
index 0000000..cc68626
--- /dev/null
+++ b/tests/repro/no-useless-assignment-try-catch.js
@@ -0,0 +1,41 @@
+/**
+ * @fileoverview Reproduction for no-useless-assignment false positive when a
+ * try block contains a `return` and the assigned value is read in `catch`.
+ */
+"use strict";
+
+const { Linter } = require("../../lib/api");
+
+const code = `async function fn() {
+  let intermediaryValue;
+  try {
+    intermediaryValue = 42;
+    unsafeFn();
+    return { error: undefined };
+  } catch {
+    return { intermediaryValue };
+  }
+}
+
+function unsafeFn() {
+  throw new Error();
+}
+`;
+
+const linter = new Linter();
+const messages = linter.verify(code, [
+    {
+        languageOptions: { ecmaVersion: "latest", sourceType: "module" },
+        rules: { "no-useless-assignment": "warn" }
+    }
+]);
+
+console.log(`ESLint ${Linter.version}`);
+console.log(JSON.stringify(messages.map(({ ruleId, line, column, message }) => ({ ruleId, line, column, message })), null, 2));
+
+if (messages.length > 0) {
+    console.log("BUG REPRODUCED: `intermediaryValue = 42` flagged although it is read in the catch block.");
+    process.exitCode = 1;
+} else {
+    console.log("No false positive.");
+}
